// bad arguments (script layer), both spellings, from N10
const badTails = ['(a, b);', '(a);', '();', '(a, b, "tall");', '(a, 7, 30);'];
const badOf = (name) => badTails.map((t) => N10.find((r) => r.name === name && r.call.endsWith(name + t)));
